'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { describe, it } = require('node:test');

// AI: below section was generated by an AI
const modulePath = path.join(__dirname, '..', 'usermods', 'ledwall');
const header = fs.readFileSync(path.join(modulePath, 'web_ui.h'), 'utf8');
const page = header.match(/R"LEDWALL\(([\s\S]*?)\)LEDWALL";/);
assert.ok(page, 'The embedded page must have one extractable raw HTML asset');
const html = page[1];
const scripts = [...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].map(match => match[1]);
const application = scripts.find(script => script.includes('function validateSnapshot('));
assert.ok(application, 'The production editor script must be present');
const fixture = JSON.parse(fs.readFileSync(path.join(modulePath, 'example-7m-3m.json'), 'utf8'));

// Execute the real import validator without a browser or a copied implementation.
function loadValidator() {
	const names = application.match(/const effectNames = \[[^;]+;/);
	const validator = application.match(/function validateSnapshot\(value\) \{[\s\S]*?\n\t\t\}/);
	assert.ok(names && validator, 'The production validator must be extractable');
	const sandbox = {};
	vm.createContext(sandbox);
	new vm.Script(names[0] + '\n' + validator[0] + '\nthis.validate = validateSnapshot;', {filename:'ledwall-validator.js'}).runInContext(sandbox);
	return sandbox.validate;
}

function snapshot() { return JSON.parse(JSON.stringify(fixture)); }

// Use the production inventory importer and diagnostic formatter in an isolated JS realm.
function loadRemoteHelpers() {
	const sandbox = {effectNames:['rainbow','wave','ripple','noise']}; vm.createContext(sandbox);
	const functions = ['validateSnapshot','layoutWithDevice','deviceDiagnostics','nextId'].map(name => {
		const match = application.match(new RegExp('function '+name+'\\([^\\n]*\\) \\{[\\s\\S]*?\\n\\t\\t\\}'));
		if (name === 'nextId') return application.match(/function nextId\(items\) \{[^\n]*\}/)[0];
		assert.ok(match, name+' must be extractable'); return match[0];
	});
	new vm.Script(functions.join('\n')+'\nthis.importDevice=layoutWithDevice;this.diagnostics=deviceDiagnostics;').runInContext(sandbox);
	return sandbox;
}
function remote() {
	return {ip:'192.168.1.51',name:'Slave',health:'online',ageMs:1000,leds:300,configKnown:true,outputsImportable:true,outputsTruncated:false,outputs:[{start:0,count:210,type:22,reverse:false},{start:210,count:90,type:30,reverse:true}],dmxAddress:1,offset:0,on:true,mode:'DDP',receivingFromMaster:true};
}

describe('LED Wall remote inventory and diagnostics', () => {
	it('keeps matching wall geometry when importing real hardware output ranges', () => {
		const original = snapshot(), before = JSON.stringify(original);
		const result = loadRemoteHelpers().importDevice(original,remote(),1);
		assert.equal(JSON.stringify(original),before,'Import must not mutate the active draft before validation');
		assert.equal(JSON.stringify(result.strips.find(strip=>strip.id===1)),JSON.stringify(original.strips[0]));
		assert.equal(result.controllers.length,2);
	});
	it('adds a discovered controller with one spatial strip per hardware output, including gaps', () => {
		const device = remote(); device.ip='192.168.1.99'; device.leds=70; device.outputs=[{start:10,count:20,type:22},{start:50,count:20,type:22}];
		const result = loadRemoteHelpers().importDevice(snapshot(),device);
		const added = result.controllers.find(item=>item.ip===device.ip), strips=result.strips.filter(item=>item.controller===added.id);
		assert.equal(added.leds,70); assert.equal(strips.length,2); assert.equal(strips[0].start,10); assert.equal(strips[1].start,50);
		assert.equal(new Set(result.strips.map(item=>item.id)).size,result.strips.length);
	});
	for (const health of ['offline','unknown','stale']) it('rejects '+health+' cached inventories',()=>{
		const device=remote(); device.health=health; assert.throws(()=>loadRemoteHelpers().importDevice(snapshot(),device));
	});
	it('rejects locked, truncated, unsupported and oversized inventories without changing the draft',()=>{
		for (const change of [{configKnown:false},{outputsTruncated:true},{outputsImportable:false},{leds:4096}]) {
			const original=snapshot(), before=JSON.stringify(original), device={...remote(),...change};
			assert.throws(()=>loadRemoteHelpers().importDevice(original,device)); assert.equal(JSON.stringify(original),before);
		}
	});
	it('distinguishes HTTP online from DDP reception and identifies receiver override',()=>{
		const helper=loadRemoteHelpers(), device=remote(); device.receivingFromMaster=false;device.live=false;device.override=2;
		const text=helper.diagnostics(device,{leds:150},{enabled:true});
		assert.match(text,/ONLINE/); assert.match(text,/live override/); assert.match(text,/LED count differs/); assert.match(text,/No realtime reception/);
		device.receivingFromMaster=true; assert.match(helper.diagnostics(device,{leds:300},{enabled:true}),/reports DDP from this master/);
	});
});

describe('Embedded LED Wall editor', () => {
	it('compiles every inline script from the actual firmware page', () => {
		assert.ok(scripts.length >= 2);
		for (let index = 0; index < scripts.length; index++) assert.doesNotThrow(() => new vm.Script(scripts[index], {filename:'ledwall-script-' + index + '.js'}));
	});

	it('gives every static HTML control a unique ID', () => {
		const ids = [...html.matchAll(/\bid="([^"]+)"/g)].map(match => match[1]);
		assert.ok(ids.length > 20);
		assert.equal(ids.length, new Set(ids).size);
	});

	it('accepts the shared 600-LED example snapshot', () => {
		const value = snapshot();
		assert.equal(loadValidator()(value), value);
		assert.equal(value.controllers.reduce((total, controller) => total + controller.leds, 0), 600);
	});

	it('starts empty and disabled until a real master layout is loaded', () => {
		const initial = application.match(/let config = ([\s\S]*?);\n\t\tlet selectedId/);
		assert.ok(initial);
		const value = vm.runInNewContext('(' + initial[1] + ')');
		assert.equal(loadValidator()(value).enabled, false);
		assert.equal(value.controllers.length,0); assert.equal(value.strips.length,0);
	});

	it('advances rainbow hue in the same positive temporal direction as firmware', () => {
		const preview = application.match(/function previewColor\(x,y,time\) \{[\s\S]*?\n\t\t\}/);
		assert.ok(preview);
		const config = snapshot(); config.effect.name = 'rainbow'; config.effect.speed = 0.1;
		const sandbox = {config}; vm.createContext(sandbox);
		new vm.Script(preview[0] + '\nthis.preview = previewColor;').runInContext(sandbox);
		const hue = Number(sandbox.preview(0, 0, 1).match(/^hsl\(([^ ]+)/)[1]);
		assert.ok(Math.abs(hue - 36) < 0.001, 'One second at 0.1 cycles/s should advance hue by 36 degrees');
	});

	for (const name of ['rainbow', 'wave', 'ripple', 'noise']) {
		it('accepts the ' + name + ' effect', () => {
			const value = snapshot();
			value.effect.name = name;
			assert.equal(loadValidator()(value).effect.name, name);
		});
	}

	const invalidCases = [
		['overlapping physical LED ranges', value => { value.strips[1].start = 0; }],
		['unknown controller references', value => { value.strips[0].controller = 900; }],
		['out-of-canvas coordinates', value => { value.strips[0].x2 = value.canvas.width + 1; }],
		['duplicate controller addresses', value => { value.controllers[1].ip = value.controllers[0].ip; }],
		['multicast destinations', value => { value.controllers[0].ip = '239.1.1.1'; }],
		['strings in numeric IDs', value => { value.strips[0].id = '<img src=x onerror=alert(1)>'; }],
		['non-finite effect speed', value => { value.effect.speed = NaN; }],
		['unsupported schema versions', value => { value.version = 2; }],
		['output allocations above 4096 LEDs', value => { value.controllers[0].leds = 4000; }],
		['missing effect parameters', value => { delete value.effect.wavelength; }],
		['fractional physical LED counts', value => { value.strips[0].count = 10.5; }],
		['non-array strip collections', value => { value.strips = {}; }]
	];
	for (const [name, mutate] of invalidCases) {
		it('rejects ' + name + ' before import or submission', () => {
			const value = snapshot();
			mutate(value);
			assert.throws(() => loadValidator()(value));
		});
	}
});
